751	    func pinched(by magnification: CGFloat) {
752	        pinchAccumulator += magnification
753	        while abs(pinchAccumulator) >= Self.pinchStep {
754	            let direction = pinchAccumulator > 0 ? 1 : -1
755	            pinchAccumulator -= CGFloat(direction) * Self.pinchStep
756	            onZoomStep?(direction)
757	        }
758	    }
